        "ios.scan12.prompt.solve": "Λύσε την άσκηση του συνημμένου εγγράφου βήμα βήμα: ένα βήμα ανά παράγραφο, πρώτα τι κάνεις σε μία πρόταση, μετά τον υπολογισμό ή το επιχείρημα. Τους τύπους σε LaTeX ανάμεσα σε $ και $. Τελείωσε με την απάντηση σε **έντονα**.",
        "ios.scan12.prompt.equation": "Λύσε την εξίσωση του συνημμένου εγγράφου. Ένα βήμα ανά παράγραφο: μια σύντομη πρόταση που λέει τι κάνεις, μετά η γραμμή του υπολογισμού σε LaTeX ανάμεσα σε $ και $. Τελείωσε με τη λύση σε **έντονα** και επαλήθευσέ τη σε μία γραμμή. Αν υπάρχουν πολλές εξισώσεις, ξεκίνα από την πρώτη.",
        "ios.scan12.prompt.explain": "Εξήγησέ μου απλά το απόσπασμα του μαθήματος στο συνημμένο έγγραφο: πρώτα την κεντρική ιδέα σε μία πρόταση, μετά τι πρέπει να καταλάβω, με ένα συγκεκριμένο παράδειγμα. Τις βασικές έννοιες σε **έντονα**.",
        "ios.scan12.prompt.vocabulary": "Βρες στο συνημμένο έγγραφο τις τρεις έως έξι πιο χρήσιμες λέξεις ή εκφράσεις για να μάθω. Για την καθεμία, μια παράγραφο που ξεκινά με τη λέξη σε έντονα και άνω-κάτω τελεία (**λέξη**: …), μετά τον ορισμό της σε μία πρόταση, μετά ένα παράδειγμα σε *πλάγια*. Τίποτα άλλο.",
        "ios.scan12.prompt.translate": "Μετάφρασε στα ελληνικά το κείμενο του συνημμένου εγγράφου, γραμμή γραμμή: κάθε γραμμή του εγγράφου γίνεται μία μεταφρασμένη γραμμή, με την ίδια σειρά, η καθεμία στη δική της παράγραφο. Χωρίς εισαγωγή και χωρίς σχόλια. Αν το κείμενο είναι πολύ μεγάλο, μετάφρασε την αρχή και πες πού σταματάς.",
        "ios.scan12.prompt.flashcards": "Φτιάξε μου κάρτες επανάληψης από το συνημμένο έγγραφο.",
        "ios.scan12.prompt.summary": "Κάνε σύνοψη του συνημμένου εγγράφου: την κεντρική ιδέα σε μία πρόταση, μετά τα τρία έως πέντε βασικά σημεία, μια σύντομη παράγραφο για το καθένα, τις βασικές έννοιες σε **έντονα**.",
